// js-01 完整示例：同一个值，在赋值、传参、比较、转换里为什么不一致

// 1) 原始值按值复制，对象复制的是引用
let num = 1
const box = { n: 1 }
const alias = box
alias.n = 2
console.log(box.n) // 2：alias 和 box 指向同一个对象

// 2) const 锁的是绑定，不是对象内容
const list = [1, 2]
list.push(3)
// list = []           // TypeError: Assignment to constant variable.
console.log(list.length) // 3

// 3) 传参：改形参不影响外面，改属性会
function mutate(x, y) {
  x = 99 // 只让形参 x 指向新值
  y.n = 99 // 顺着引用改到同一个对象
}
mutate(num, box)
console.log(num, box.n) // 1 99

// 4) 比较：对象比地址，原始值比值
console.log({ n: 1 } === { n: 1 }) // false
console.log('1' == 1, '1' === 1) // true false

// 5) 隐式转换：ToPrimitive 先问 valueOf，再问 toString
const price = {
  valueOf: () => 10,
  toString: () => '10元',
}
console.log(price + 1) // 11：+ 走 default 提示，valueOf 先命中
console.log(`${price}`) // 10元：模板字符串要字符串，toString 命中
console.log([] + {}) // [object Object]
console.log(1 + '2', '12' - 1, 1 + 2 + '3') // 12 11 33

// 6) NaN 与 Object.is
console.log(NaN === NaN, Object.is(NaN, NaN)) // false true
console.log(0 === -0, Object.is(0, -0)) // true false
console.log(Number.isNaN('abc'), isNaN('abc')) // false true

// 7) 装箱：原始值临时包了一层对象
const s = 'abc'
console.log(s.length, s.toUpperCase()) // 3 ABC
console.log(typeof s, typeof new String('abc')) // string object
console.log(typeof null, typeof 1n, typeof Symbol()) // object bigint symbol

// js-02 完整示例：闭包捕获的是变量，不是那一刻的值

// 1) 多个闭包共享同一个环境里的绑定
function makeCounter() {
  let count = 0
  return {
    inc: () => ++count,
    get: () => count,
  }
}
const c1 = makeCounter()
c1.inc()
c1.inc()
console.log(c1.get()) // 2
const c2 = makeCounter()
console.log(c2.get()) // 0：每次调用新建一个环境

// 2) 循环里的 var 共享一个绑定，let 每轮新建
const byVar = []
for (var i = 0; i < 3; i++) byVar.push(() => i)
console.log(byVar.map(f => f())) // [ 3, 3, 3 ]

const byLet = []
for (let j = 0; j < 3; j++) byLet.push(() => j)
console.log(byLet.map(f => f())) // [ 0, 1, 2 ]

// 3) 默认参数只在没传或传 undefined 时生效，且每次调用重新求值
let seq = 0
function label(name = 'anon', tag = `${name}#${++seq}`) {
  return tag
}
console.log(label(), label('a'), label('b')) // anon#1 a#2 b#3
console.log(label(undefined, undefined)) // anon#4
console.log(label(null)) // null#5

// 4) 箭头函数没有自己的 this / arguments
function pick() {
  const self = this
  return {
    name: 'inner',
    regular() { return this.name },
    arrow: () => self.name,
    firstArg: () => arguments[0],
  }
}
const picked = pick.call({ name: 'outer' }, 'arg0')
console.log(picked.regular()) // inner：看调用点
console.log(picked.arrow()) // outer：定义时锁定
console.log(picked.firstArg()) // arg0：借的是 pick 的 arguments

// 5) rest 是真数组，arguments 是类数组
function sum(first, ...rest) {
  console.log(Array.isArray(rest), Array.isArray(arguments)) // true false
  return first + rest.reduce((a, b) => a + b, 0)
}
console.log(sum(1, 2, 3)) // 6

// 6) 作用域链在定义时确定，与调用位置无关
const who = 'global'
function outer() {
  const who = 'outer'
  return inner() // 虽然是在 outer 里调用，inner 并不看 outer 的 who
}
function inner() {
  return who
}
console.log(outer()) // global

// 7) 闭包拖住被引用的数据：不再需要时断开引用
function makeReader(rows) {
  return () => rows.length
}
let read = makeReader(new Array(1e5).fill(0))
console.log(read()) // 100000
read = null // 没有其它引用后，闭包与 rows 才可回收

