// js-03 完整示例：三件套各自的返回物与边界

const orders = [
  { id: 1, user: 'ann', amount: 120 },
  { id: 2, user: 'bob', amount: 80 },
  { id: 3, user: 'ann', amount: 300 },
]

// 1) map：一对一，长度永远不变
console.log(orders.map(o => o.id)) // [ 1, 2, 3 ]

// 2) filter：只做筛选，回调应返回布尔
const big = orders.filter(o => o.amount >= 100)
console.log(big.map(o => o.id)) // [ 1, 3 ]

// 3) reduce：把数组压成一个值
console.log(orders.reduce((sum, o) => sum + o.amount, 0)) // 500

// 4) 一次遍历同时做 groupBy 与 countBy
const stats = orders.reduce((acc, o) => {
  const g = (acc[o.user] ??= { count: 0, amount: 0 })
  g.count += 1
  g.amount += o.amount
  return acc
}, {})
console.log(stats)
// { ann: { count: 2, amount: 420 }, bob: { count: 1, amount: 80 } }

// 5) 累加器陷阱：空数组 + 不给初始值
try {
  ;[].reduce((a, b) => a + b)
} catch (e) {
  console.log(e.constructor.name) // TypeError
}
console.log([5].reduce((a, b) => a + b)) // 5：首元素当累加器，回调一次都没跑
console.log([0, 1, 2].reduce((a, b) => a + b)) // 3
console.log(['1', '2'].reduce((a, b) => a + b, 0)) // 012：0 + '1' 先变成字符串

// 6) 稀疏数组：三件套都会跳过空槽
const sparse = [1, , 3]
console.log(sparse.length) // 3
console.log(sparse.map(x => x * 2)) // [ 2, <1 empty item>, 6 ]
console.log(sparse.filter(() => true).length) // 2
console.log([...sparse].length) // 3：展开把空槽变成 undefined

// 7) forEach 不能 break，需要提前退出就换方法
const nums = [1, 2, 3, 4]
const seen = []
nums.forEach(n => {
  if (n > 2) return // 只是跳过本次回调
  seen.push(n)
})
console.log(seen) // [ 1, 2 ]

console.log(orders.find(o => o.amount > 200).id) // 3：找到就停
console.log(nums.some(n => n > 3), nums.every(n => n > 0)) // true true
console.log([].every(n => n > 0)) // true：空数组的 every 恒为真

// 8) 可变方法会原地改数组
const raw = [10, 9, 100]
const sorted = raw.sort() // 默认按字符串比较，而且改的是原数组
console.log(sorted === raw, raw) // true [ 10, 100, 9 ]
const asc = [...raw].sort((a, b) => a - b)
console.log(asc, raw) // [ 9, 10, 100 ] [ 10, 100, 9 ]

const queue = ['a', 'b', 'c']
const removed = queue.splice(1, 1) // 原地删除
console.log(queue, removed) // [ 'a', 'c' ] [ 'b' ]
const inserted = [...queue.slice(0, 1), 'x', ...queue.slice(1)]
console.log(inserted) // [ 'a', 'x', 'c' ]

'use strict'

// 1) 浅拷贝：只复制第一层，嵌套对象仍是同一个引用
const defaults = { theme: 'light', editor: { fontSize: 14, tabSize: 2 } }
const shallow = { ...defaults }
shallow.editor.fontSize = 20
console.log(defaults.editor.fontSize) // 20 —— 原对象被改

// 2) 只复制被修改路径上的每一层，其余子树复用引用
const user = { ...defaults, editor: { ...defaults.editor, fontSize: 16 } }
console.log(user.editor.fontSize, defaults.editor.fontSize) // 16 20
console.log(user.editor === defaults.editor) // false
console.log(user.theme, user.editor.tabSize) // light 2

// 3) structuredClone 能处理循环引用
const state = { count: 0, self: null }
state.self = state
const cloned = structuredClone(state)
console.log(cloned !== state, cloned.self === cloned) // true true

// 4) 但 structuredClone 会丢原型、拒绝函数
