  constructor() {
    this.x = 1
  }
  distance() {
    return this.x
  }
}
const p = structuredClone(new Point())
console.log(p instanceof Point, typeof p.distance) // false undefined
try {
  structuredClone({ fn: () => 1 })
} catch (err) {
  console.log(err.name) // DataCloneError
}

