// 全部任务用 setTimeout 模拟，不联网，可直接在 Node 20+ 运行
const sleep = (ms, value) => new Promise((resolve) => setTimeout(() => resolve(value), ms))
const fail = (ms, message) => new Promise((_, reject) => setTimeout(() => reject(new Error(message)), ms))

// 并发上限为 limit 的 map，结果顺序与输入一致
async function mapLimit(items, limit, fn) {
  const results = new Array(items.length)
  let cursor = 0
  const worker = async () => {
    while (cursor < items.length) {
      const index = cursor++
      results[index] = await fn(items[index], index)
    }
  }
  const size = Math.min(limit, items.length)
  await Promise.all(Array.from({ length: size }, () => worker()))
  return results
}

// 能被 AbortSignal 取消的任务
function runTask(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal.aborted) {
      reject(signal.reason)
      return
    }
    const timer = setTimeout(() => resolve(`done in ${ms}ms`), ms)
    signal.addEventListener(
      'abort',
      () => {
        clearTimeout(timer)
        reject(signal.reason)
      },
      { once: true },
    )
  })
}

async function main() {
  // 1) 串行 vs 并行：同样的 3 个 150ms 任务
  const serialStart = Date.now()
  const serial = []
  for (const id of [1, 2, 3]) serial.push(await sleep(150, id))
  console.log('serial', serial, Date.now() - serialStart) // [1,2,3] ≈450

  const parallelStart = Date.now()
  const parallel = await Promise.all([1, 2, 3].map((id) => sleep(150, id)))
  console.log('parallel', parallel, Date.now() - parallelStart) // [1,2,3] ≈150

  // 2) allSettled 保留每一项的成败，顺序与输入一致
  const settled = await Promise.allSettled([sleep(30, 'ok'), fail(10, 'boom')])
  console.log(settled.map((r) => r.status)) // ['fulfilled', 'rejected']
  console.log(settled[0].value, settled[1].reason.message) // ok boom

  // 3) any：第一个成功；全部失败才抛 AggregateError
  console.log(await Promise.any([fail(10, 'a'), sleep(20, 'win')])) // win
  try {
    await Promise.any([fail(10, 'a'), fail(20, 'b')])
  } catch (err) {
    console.log(err.name, err.errors.map((e) => e.message)) // AggregateError ['a','b']
  }

  // 4) 限流：5 个任务、并发 2，共 3 轮
  const started = Date.now()
  const results = await mapLimit([1, 2, 3, 4, 5], 2, async (n) => {
    await sleep(100)
    return n * 2
  })
  console.log(results, Date.now() - started) // [2,4,6,8,10] ≈300（含调度开销，实测 300–350）

  // 5) 取消：50ms 后 abort，200ms 的任务以 AbortError 结束
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(new DOMException('timeout', 'AbortError')), 50)
  try {
    await runTask(200, controller.signal)
  } catch (err) {
    console.log(err.name) // AbortError
  } finally {
    clearTimeout(timer)
  }
}

main()

