// js-07 示例：数据 → 界面，一次构建、一个监听器、读写分离
// 粘到任意页面控制台即可运行（重复运行会复用同一个容器，不堆 DOM）

let root = document.getElementById('demo-07')
if (!root) {
  root = document.createElement('div')
  root.id = 'demo-07'
  document.body.append(root)
}
root.replaceChildren()   // 只清内容，容器本身留着，监听器才有稳定的挂载点

// 1) 数据是唯一真相源，DOM 只是它的投影
const state = [
  { id: 1, text: '读完 SPEC 的七段结构', done: false },
  { id: 2, text: '<img src=x onerror="alert(1)">', done: false }, // 用户输入：走 innerHTML 会弹窗
  { id: 3, text: '跑一遍校验脚本', done: true },
]

// 2) 构建：先在 DocumentFragment 里攒好，最后只插一次
function build(items) {
  const frag = document.createDocumentFragment()
  for (const item of items) {
    const li = document.createElement('li')
    li.dataset.id = String(item.id)
    li.className = item.done ? 'done' : ''

    const box = document.createElement('input')
    box.type = 'checkbox'
    box.checked = item.done

    const text = document.createElement('span')
    text.textContent = item.text      // 只用 textContent：用户数据永远不会变成标签
    text.style.marginLeft = '6px'

    li.append(box, text)
    frag.append(li)
  }
  return frag                          // 还没进文档树，零重排
}

const list = document.createElement('ul')
list.id = 'todo-07'
list.style.cssText = 'font:14px/1.9 system-ui;padding-left:18px;width:max-content'
list.append(build(state))              // 一次性入树 = 一次重排
root.append(list)

// 3) 委托：整个列表只有一个 click 监听器，之后新增的 li 自动生效
list.addEventListener('click', (e) => {
  const li = e.target.closest('li')
  if (!li || !list.contains(li)) return   // 点在列表空白处，或 closest 穿出了列表
  const item = state.find((it) => it.id === Number(li.dataset.id))
  if (!item) return                       // 数据里没有的 id 不处理：DOM 不是真相源

  item.done = !item.done                  // 先改数据
  li.classList.toggle('done', item.done)  // 再改界面
  li.querySelector('input').checked = item.done
  console.log('toggle', item.id, item.done)
})

// 4) 读写分离：一次读完布局，再统一写样式，避免「写-读-写」强制同步布局
requestAnimationFrame(() => {
  const height = list.getBoundingClientRect().height  // 只读一次
  list.style.borderLeft = '3px solid #4c8dff'
  list.style.paddingTop = '4px'
  list.style.background = '#f7f9ff'
  console.log('list height =', Math.round(height))
})

// 5) 解绑：same 函数引用，或一个 signal 管一组监听器；once 让它自己退场
const ac = new AbortController()
window.addEventListener('keydown', (e) => console.log('[once] key =', e.key), {
  once: true,
  signal: ac.signal,
})
// 提前取消就 ac.abort()：比 removeEventListener 少记一个函数引用

console.log('已渲染', state.length, '行；点复选框或文字试试，再按任意键')

