// js-08 示例：请求 → 状态 → 渲染，三段各自可测
// Node 20+ 或浏览器控制台直接运行（用 data: URL 模拟后端，不依赖网络）
// 真实工程里这三段在 api.js / view.js / main.js 三个模块中，用 export/import 连接；
// 为了让示例能整段粘贴运行，这里合并成一个文件，不写 import/export。

const API = 'data:application/json,' + encodeURIComponent(JSON.stringify([
  { id: 1, name: '林一', email: 'lin@example.com' },
  { id: 2, name: '  ', email: 'a<b@example.com' },  // 名字只有空格 + 需要转义的字符
  { email: 'no-id@example.com' },                   // 缺 id，应被过滤
]))

// ① 请求层：只管「怎么拿到 JSON」，并把各种失败折叠成同一种异常
// 非 2xx 自己抛错（fetch 不会），超时用 AbortSignal.timeout，只重试可重试的错误
async function fetchJson(url, { timeout = 3000, retries = 1 } = {}) {
  try {
    const res = await fetch(url, { signal: AbortSignal.timeout(timeout) })
    if (!res.ok) {
      const err = new Error(`HTTP ${res.status} ${res.statusText}`, { cause: res })
      err.status = res.status
      err.retryable = res.status >= 500 || res.status === 429
      throw err
    }
    return await res.json()   // body 只能读一次，所以这里不 clone
  } catch (err) {
    // 网络错误是 TypeError，超时是 name === 'TimeoutError'；二者都值得重试一次
    const retryable = err.retryable || err.name === 'TimeoutError' || err instanceof TypeError
    if (retries > 0 && retryable) {
      return fetchJson(url, { timeout, retries: retries - 1 })
    }
    throw err
  }
}

// ② 状态层：纯函数，把「接口返回」变成「界面需要的数据」
function toViewModel(list) {
  return list
    .filter((u) => u.id != null)              // 没有 id 的记录无法定位，直接丢掉
    .map((u) => ({
      id: u.id,
      name: u.name?.trim() || '（未命名）',    // 空白名字给占位，别让界面出现空洞
      email: u.email ?? '',
    }))
}

// ③ 渲染层：纯函数，state → HTML 字符串；转义只在这一个出口做
const ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }
const esc = (value) => String(value).replace(/[&<>"']/g, (ch) => ESC[ch])

function view(state) {
  if (state.status === 'loading') return '<p>加载中…</p>'
  if (state.status === 'error') return `<p class="err">${esc(state.message)}</p>`
  if (state.data.length === 0) return '<p>暂无数据</p>'
  const items = state.data
    .map((u) => `<li data-id="${u.id}"><b>${esc(u.name)}</b> ${esc(u.email)}</li>`)
    .join('')
  return `<ul>${items}</ul>`
}

// ④ 组装层：只负责把三段接起来，以及「loading → 成功/失败」的状态流转
async function main() {
  const states = [{ status: 'loading' }]
  try {
    const data = await fetchJson(API)
    states.push({ status: 'ready', data: toViewModel(data) })
  } catch (err) {
