// js-12 示例：把「失败」变成可诊断的数据
// 浏览器控制台或 Node 20 直接运行；预期输出见文件末尾注释

// 1) 自定义错误：机器可读的 code + 上下文 + 原始错误，三者都不塞进 message
class AppError extends Error {
  constructor(message, { code = 'E_APP', cause, context = {} } = {}) {
    super(message, { cause })  // 第二个参数才是 { cause }；写成 super(message, cause) 会静默丢掉
    this.name = 'AppError'
    this.code = code
    this.context = context
  }
}

// 2) 只有这一处决定「给用户看什么」；未知错误一律兜底，绝不把原始 message 抛给用户
const USER_MESSAGE = {
  E_ARGS: '请先选择用户',
  E_NET: '网络不稳定，请稍后重试',
  E_TIMEOUT: '请求超时，请稍后重试',
}
const toUserMessage = (err) => USER_MESSAGE[err?.code] ?? '出了点问题，请稍后再试'

// 3) 一次「底层报错 → 包一层 → 上层决策」的调用链
async function loadOrders(userId) {
  try {
    if (!userId) throw new TypeError('userId is required')  // 参数错误：重试也没用
    // 模拟一次真实网络往返，10ms 后失败
    await new Promise((_, reject) => setTimeout(() => reject(new Error('socket hang up')), 10))
    return []
  } catch (err) {
    // 用 cause 把原始错误挂上去，否则根因和原始堆栈在这里就断了
    const code = err instanceof TypeError ? 'E_ARGS' : 'E_NET'
    throw new AppError('加载订单失败', { code, cause: err, context: { userId } })
  }
}

// 4) 统一出口：一行结构化日志 + 一句人话，两者不混在一起
function report(err, where) {
  const code = err?.code ?? 'E_UNKNOWN'
  const cause = err?.cause?.message ?? '-'
  console.log(`[${where}] ${code} | ${err?.message ?? '-'} | cause=${cause}`)
  return toUserMessage(err)
}

// 5) 全局兜底：只接「漏网的」，真正的处理仍然在本地
function onUnhandled(reason) {
  console.log(`[全局兜底] ${reason?.code ?? reason?.name ?? 'unknown'} | ${reason?.message ?? reason}`)
}
if (typeof window !== 'undefined') {
  window.addEventListener('unhandledrejection', (e) => onUnhandled(e.reason))
} else if (typeof process !== 'undefined') {
  process.on('unhandledRejection', onUnhandled)
}

// 6) 三种失败 + 一个故意漏网的 rejection
async function run() {
  console.log('--- A 参数缺失 ---')
  console.log('→', report(await loadOrders(null).catch((e) => e), 'loadOrders'))

  console.log('--- B 网络失败 ---')
  console.log('→', report(await loadOrders(42).catch((e) => e), 'loadOrders'))

  console.log('--- C 未知错误 ---')
  console.log('→', report(new Error('boom'), 'renderHome'))

  console.log('--- D 漏网的 rejection ---')
  loadOrders(42)  // 故意不 await：本地 try/catch 接不到它，只能由全局钩子接住
  console.log('（本地 catch 不会执行，稍后由 unhandledrejection 打印）')
}

run()

// 预期输出（顺序与内容都稳定）：
// --- A 参数缺失 ---
// [loadOrders] E_ARGS | 加载订单失败 | cause=userId is required
// → 请先选择用户
// --- B 网络失败 ---
// [loadOrders] E_NET | 加载订单失败 | cause=socket hang up
// → 网络不稳定，请稍后重试
// --- C 未知错误 ---
// [renderHome] E_UNKNOWN | boom | cause=-
// → 出了点问题，请稍后再试
// --- D 漏网的 rejection ---
// （本地 catch 不会执行，稍后由 unhandledrejection 打印）
// [全局兜底] E_NET | 加载订单失败

