// 运行环境：Node 20+ 或任意浏览器 Console，输出完全确定。
// 这里用「虚拟时钟」代替真实计时器：时间变成可以手动推进的变量，
// 才能断言「第几毫秒执行了几次」，而不是靠 sleep 猜。

// ---------- 可控时钟 ----------
let now = 0;
const timers = []; // { at, fn }

function later(fn, ms) {
  timers.push({ at: now + ms, fn });
  return fn;
}
function clearLater(handle) {
  const i = timers.findIndex((t) => t.fn === handle);
  if (i !== -1) timers.splice(i, 1);
}
function advance(ms) {
  const target = now + ms;
  for (;;) {
    timers.sort((a, b) => a.at - b.at);
    const next = timers[0];
    if (!next || next.at > target) break;
    timers.shift();
    now = next.at;
    next.fn();
  }
  now = target;
}

// ---------- 防抖：安静 wait 毫秒后只执行最后一次 ----------
function debounce(fn, wait) {
  let handle = null;
  const debounced = (...args) => {
    if (handle) clearLater(handle);            // 关键：每次调用都取消上一次
    handle = () => {
      handle = null;
      fn(...args);                             // 用最后一次的参数
    };
    later(handle, wait);
  };
  debounced.cancel = () => {
    if (handle) clearLater(handle);
    handle = null;                             // 卸载时必须能取消，否则回调打到已销毁的实例
  };
  return debounced;
}

// ---------- 节流：每个 wait 窗口最多执行一次（首尾都补） ----------
function throttle(fn, wait) {
  let last = -Infinity;
  let handle = null;
  let lastArgs;
  const throttled = (...args) => {
    lastArgs = args;
    if (now - last >= wait) {
      last = now;
      fn(...args);                             // 窗口起点：立即执行
      return;
    }
    if (handle) return;                        // 窗口内已有尾调用，不重复排队
    handle = () => {
      handle = null;
      last = now;
      fn(...lastArgs);                         // 窗口末尾补一次，避免丢掉最后一次
    };
    later(handle, wait - (now - last));
  };
  throttled.cancel = () => {
    if (handle) clearLater(handle);
    handle = null;
    last = -Infinity;
  };
  return throttled;
}

// ---------- 1. 防抖：连续三次输入，只有最后一次活下来 ----------
const save = debounce((v) => console.log(`t=${now} save:${v}`), 100);
save('a');          // t=0   排队到 100
advance(30);
save('b');          // t=30  取消上一次，改排到 130
advance(30);
save('c');          // t=60  取消上一次，改排到 160
advance(100);       // 时钟走到 160，正好触发最后一次

// ---------- 2. 节流：四次调用跨三个窗口，窗口末尾各补一次 ----------
const tick = throttle(() => console.log(`t=${now} tick`), 100);
for (let i = 0; i < 4; i++) {
  tick();           // t=160 / 200 / 240 / 280
  advance(40);
}
advance(200);       // 让窗口末尾的补调用有机会执行

// ---------- 3. cancel：取消后不再有任何回调 ----------
let fired = 0;
const risky = debounce(() => { fired += 1; }, 50);
risky();
risky.cancel();     // 模拟组件卸载
advance(500);
console.log('cancel 之后触发次数:', fired);

// ---------- 4. WeakMap：对象做键的缓存不阻止回收 ----------
const sizeCache = new WeakMap();
const node = { id: 'row-1' };
sizeCache.set(node, { height: 40 });
console.log('weakmap 命中:', sizeCache.has(node), sizeCache.get(node));

// 预期输出：
//   t=160 save:c
//   t=160 tick
//   t=260 tick
//   t=360 tick
//   cancel 之后触发次数: 0
//   weakmap 命中: true { height: 40 }

