// 运行环境：
//   Node 20+  → 只执行计算部分，打印可见区间，输出完全确定。
//   浏览器    → 额外渲染 5000 行虚拟列表；页面里需要一个
//               <div id="viewport" style="height:400px;overflow:auto"></div>
//
// 预期输出（Node）：
//   scrollTop=0      → [0, 20) 共 20 行
//   scrollTop=1600   → [35, 55) 共 20 行
//   scrollTop=199600 → [4985, 5000) 共 15 行
//
// 浏览器里还会打印「已渲染行数: 20」，并且始终只有 20 个 .row 节点。

const TOTAL = 5000;
const ROW_H = 40;
const VIEW_H = 400;
const OVERSCAN = 5;

// 只做算术，不碰 DOM：所以可以在 Node 里断言，也可以被单测覆盖
function getVisibleRange(scrollTop, total = TOTAL, rowH = ROW_H, viewH = VIEW_H, overscan = OVERSCAN) {
  const first = Math.max(0, Math.floor(scrollTop / rowH) - overscan);
  const count = Math.ceil(viewH / rowH) + overscan * 2; // 视口行数 + 上下各一段缓冲
  const last = Math.min(total, first + count);
  return [first, last];
}

for (const st of [0, 1600, 199600]) {
  const [a, b] = getVisibleRange(st);
  console.log(`scrollTop=${st} → [${a}, ${b}) 共 ${b - a} 行`);
}

// ---------- 以下只在浏览器执行 ----------
if (typeof document !== 'undefined') {
  const viewport = document.querySelector('#viewport');
  const spacer = document.createElement('div'); // 撑出总高度，滚动条长度才正确
  spacer.style.cssText = `position:relative;height:${TOTAL * ROW_H}px`;
  viewport.append(spacer);

  const els = []; // 复用的节点池，长度始终等于可见行数

  function render() {
    const scrollTop = viewport.scrollTop;          // ① 只在这里读一次布局
    const [first, last] = getVisibleRange(scrollTop);
    const need = last - first;

    while (els.length < need) {                    // ② 不够就补节点
      const el = document.createElement('div');
      el.className = 'row';
      el.style.cssText = `position:absolute;top:0;left:0;right:0;height:${ROW_H}px`;
      spacer.append(el);
      els.push(el);
    }
    while (els.length > need) els.pop().remove();  // ③ 多了就摘掉

    for (let i = 0; i < need; i++) {               // ④ 之后全是写，不再读
      const index = first + i;
      els[i].textContent = `第 ${index + 1} 行`;
      els[i].style.transform = `translateY(${index * ROW_H}px)`; // 只走合成，不触发布局
    }
    console.log('已渲染行数:', need);
  }

  let ticking = false;
  viewport.addEventListener('scroll', () => {
    if (ticking) return;                           // ⑤ 一帧只处理一次滚动
    ticking = true;
    requestAnimationFrame(() => {
      ticking = false;
      render();                                    // ⑥ 写操作统一挪到 rAF 里
    });
  }, { passive: true });

  render();
}

// 对照：把 ④ 换成「每行读一次 offsetTop 再算位置」，滚动时
// Performance 面板里会重新出现密集的 Layout —— 读布局属性会强制结算。

